const end = new Date();
const start = new Date(end);
start.setUTCDate(end.getUTCDate() - 6);

const ymd = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    start_date: ymd(start),
    end_date: ymd(end),
    // Prefer exact field names from your Shiplab extracted invoice JSON.
    // Leave empty to auto-detect common charge field names.
    amount_field: '',
  },
}];

function collect(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  if (items.length === 1 && Array.isArray(items[0])) return items[0];
  return items.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
}

const period = $('Prepare Last 7 Days').first().json;
const profile = $('Get Profile').first().json;
const groups = collect('Get Connector Groups');
const connectors = collect('Get Connectors');

const groupsById = Object.fromEntries(
  groups.map((g) => [String(g.id), g]),
);

const catalog = connectors.map((c) => {
  const group = groupsById[String(c.company_id)] || {};
  return {
    connector_id: c.id,
    username: c.username,
    carrier: c.carrier,
    carrier_display_name: c.carrier_display_name || c.carrier,
    enabled: c.enabled,
    status: c.status,
    connector_group_id: c.company_id,
    connector_group_name: group.display_name || group.name || c.company_name || '',
  };
});

return [{
  json: {
    start_date: period.start_date,
    end_date: period.end_date,
    amount_field: period.amount_field || '',
    invoice_format: profile.invoice_format || '',
    connector_group_count: groups.length,
    connector_count: connectors.length,
    catalog,
  },
}];

const catalog = $('Build Catalog').first().json;
const response = $input.first().json;
let invoices = Array.isArray(response.invoices)
  ? response.invoices
  : Array.isArray(response)
    ? response
    : [];

// Prefer the customer's invoice_format when the same invoice appears in multiple formats.
const preferred = catalog.invoice_format;
if (preferred) {
  const matched = invoices.filter((inv) => inv.file_format === preferred);
  if (matched.length) invoices = matched;
}

const seen = new Set();
invoices = invoices.filter((inv) => {
  const key = [inv.credential_id, inv.invoice_number, inv.invoice_date].join('|');
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const byConnector = Object.fromEntries(
  (catalog.catalog || []).map((c) => [String(c.connector_id), c]),
);

if (invoices.length === 0) {
  return [{
    json: {
      _empty: true,
      start_date: catalog.start_date,
      end_date: catalog.end_date,
      message: 'No invoices found in this date range.',
      catalog: catalog.catalog,
    },
  }];
}

return invoices.map((inv) => {
  const connector = byConnector[String(inv.credential_id)] || {
    connector_id: inv.credential_id,
    connector_group_id: inv.company_id,
    carrier: inv.carrier,
  };
  return {
    json: {
      start_date: catalog.start_date,
      end_date: catalog.end_date,
      amount_field: catalog.amount_field,
      invoice_number: inv.invoice_number,
      invoice_date: inv.invoice_date,
      file_format: inv.file_format,
      signed_url: inv.signed_url,
      ...connector,
    },
  };
});

const meta = $('Has Signed URL?').item.json;
const body = $input.item.json;

const CANDIDATES = [
  meta.amount_field,
  'net_spent',
  'net_amount',
  'Net Amount',
  'NetCharges',
  'Net Charges',
  'net_charges',
  'Invoice Amount',
  'invoice_amount',
  'Amount Due',
  'amount_due',
  'Total Charges',
  'total_charges',
  'total_charge',
  'Charge',
  'charge',
  'Total',
  'total',
].filter(Boolean);

function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const n = Number(v.replace(/[,$]/g, '').trim());
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function amountFromObject(obj, field) {
  if (!obj || typeof obj !== 'object') return null;
  if (Object.prototype.hasOwnProperty.call(obj, field)) return toNumber(obj[field]);
  const lower = field.toLowerCase();
  for (const [k, v] of Object.entries(obj)) {
    if (String(k).toLowerCase() === lower) return toNumber(v);
  }
  return null;
}

function sumField(rows, field) {
  let sum = 0;
  let hits = 0;
  for (const row of rows) {
    const n = amountFromObject(row, field);
    if (n !== null) {
      sum += n;
      hits += 1;
    }
  }
  return hits ? { amount: sum, field, row_count: hits } : null;
}

function extract(payload) {
  const rows = Array.isArray(payload)
    ? payload
    : Array.isArray(payload?.data)
      ? payload.data
      : Array.isArray(payload?.packages)
        ? payload.packages
        : Array.isArray(payload?.shipments)
          ? payload.shipments
          : Array.isArray(payload?.charges)
            ? payload.charges
            : null;

  for (const field of CANDIDATES) {
    if (rows) {
      const summed = sumField(rows, field);
      if (summed) return summed;
    }
    const single = amountFromObject(payload, field);
    if (single !== null) return { amount: single, field, row_count: 1 };
  }

  return { amount: null, field: null, row_count: 0 };
}

const extracted = extract(body);

return [{
  json: {
    ...meta,
    charged_amount: extracted.amount,
    amount_field_used: extracted.field,
    charge_row_count: extracted.row_count,
    download_ok: true,
  },
}];

const items = $input.all().map((i) => ({
  json: {
    ...i.json,
    charged_amount: null,
    amount_field_used: null,
    charge_row_count: 0,
    download_ok: false,
  },
}));
return items;

const catalog = $('Build Catalog').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => !r._empty);

if ($input.first().json._empty) {
  return [{
    json: {
      period: {
        start_date: catalog.start_date,
        end_date: catalog.end_date,
      },
      connector_group_count: catalog.connector_group_count,
      connector_count: catalog.connector_count,
      invoice_count: 0,
      invoices_with_amount: 0,
      grand_total_charged: 0,
      amount_fields_seen: [],
      connectors: (catalog.catalog || []).map((c) => ({
        ...c,
        invoice_count: 0,
        total_charged: 0,
        invoices: [],
      })),
      note: 'No invoices found in this date range.',
    },
  }];
}

const byId = new Map();
for (const c of catalog.catalog || []) {
  byId.set(String(c.connector_id), {
    ...c,
    invoice_count: 0,
    total_charged: 0,
    invoices: [],
  });
}

const amountFields = new Set();
let invoicesWithAmount = 0;
let grandTotal = 0;

for (const row of rows) {
  const key = String(row.connector_id);
  if (!byId.has(key)) {
    byId.set(key, {
      connector_id: row.connector_id,
      username: row.username,
      carrier: row.carrier,
      carrier_display_name: row.carrier_display_name || row.carrier,
      connector_group_id: row.connector_group_id,
      connector_group_name: row.connector_group_name || '',
      invoice_count: 0,
      total_charged: 0,
      invoices: [],
    });
  }
  const bucket = byId.get(key);
  const amount = typeof row.charged_amount === 'number' ? row.charged_amount : null;
  if (amount !== null) {
    bucket.total_charged += amount;
    grandTotal += amount;
    invoicesWithAmount += 1;
    if (row.amount_field_used) amountFields.add(row.amount_field_used);
  }
  bucket.invoice_count += 1;
  bucket.invoices.push({
    invoice_number: row.invoice_number,
    invoice_date: row.invoice_date,
    file_format: row.file_format,
    charged_amount: amount,
    amount_field_used: row.amount_field_used,
    download_ok: row.download_ok,
  });
}

const connectors = [...byId.values()].sort((a, b) => b.total_charged - a.total_charged);

return [{
  json: {
    period: {
      start_date: catalog.start_date,
      end_date: catalog.end_date,
    },
    connector_group_count: catalog.connector_group_count,
    connector_count: catalog.connector_count,
    invoice_count: rows.length,
    invoices_with_amount: invoicesWithAmount,
    grand_total_charged: Number(grandTotal.toFixed(2)),
    amount_fields_seen: [...amountFields],
    connectors,
    note: invoicesWithAmount === 0
      ? 'Invoices were found, but no charge field matched. Open one downloaded invoice JSON and set amount_field in Prepare Last 7 Days to the exact field name.'
      : undefined,
  },
}];
